def log(event, level="info", ts=None, **fields):         # ⭐ 사건 이름 + 칸들. 말의 내용은 넣지 않음(4교시에 가려서 넣음)
    row = {"ts": ts or datetime.datetime.now().isoformat(timespec="milliseconds"), "level": level, "event": event, **fields}
    LOG.append(row); return row

